import { app } from 'electron'
import { copyFile, cp, mkdir, readFile, readdir, stat, writeFile } from 'node:fs/promises'
import path from 'node:path'

import { logger } from '../logger'

// AiPot was renamed from NeoPot. Keep the old profile data when the user
// upgrades in place: `%APPDATA%\NeoPot` -> `%APPDATA%\AiPot`.
const LEGACY_PROFILE_DIR_NAME = 'NeoPot'
const MIGRATION_MARKER = 'profile-migration.json'

// Entries that are either regenerated by Chromium or not needed for the
// migration. Copying caches would only make the first launch slower.
const SKIPPED_ENTRIES = new Set([
  'Cache',
  'Code Cache',
  'DawnGraphiteCache',
  'DawnWebGPUCache',
  'GPUCache',
  'GrShaderCache',
  'GraphiteDawnCache',
  'ShaderCache',
  'blob_storage',
  'logs',
  'Network Persistent State',
  'SingletonCookie',
  'SingletonLock',
  'SingletonSocket',
  'TransportSecurity',
  'Trust Tokens',
  'Trust Tokens-journal',
])

// Only user-owned data is migrated. Runtime caches and lock files are skipped.
const MIGRATED_ENTRIES = new Set([
  'config.json',
  'history.db',
  'legacy-backup',
  'migration.json',
  'plugins',
])

async function exists(target: string): Promise<boolean> {
  try {
    await stat(target)
    return true
  } catch {
    return false
  }
}

async function copyLegacyEntry(source: string, destination: string): Promise<void> {
  const sourceStat = await stat(source)
  if (sourceStat.isDirectory()) {
    await cp(source, destination, { recursive: true, force: false, errorOnExist: false })
    return
  }

  await copyFile(source, destination)
}

/**
 * safeStorage ciphertext is bound to the profile that produced it (the
 * OSCrypt key lives in that profile's `Local State`), so secrets copied from
 * the NeoPot profile cannot be decrypted by AiPot. Reads of those values fall
 * back to an empty string; the user has to re-enter API keys once. Plaintext
 * keys injected into config.json migrate as-is.
 */
async function warnAboutEncryptedSecrets(configPath: string): Promise<void> {
  try {
    const raw = await readFile(configPath, 'utf8')
    if (!raw.includes('__neopot_secret')) {
      return
    }

    logger.warn(
      'The migrated config contains safeStorage-encrypted secrets. They cannot be decrypted from the new profile; re-enter API keys in Settings.',
      {
        configPath,
      },
    )
  } catch {
    // The config may not exist; nothing to warn about.
  }
}

/**
 * Copies the NeoPot profile into the AiPot profile on first launch.
 *
 * The migration is intentionally conservative:
 * - never overwrites an existing AiPot config;
 * - copies only known user data (config, plugins, history, backups);
 * - writes a marker so a failed/partial copy is not repeated forever.
 */
export async function migrateLegacyProfile(): Promise<void> {
  const appData = app.getPath('appData')
  const currentUserData = app.getPath('userData')
  const legacyUserData = path.join(appData, LEGACY_PROFILE_DIR_NAME)

  if (path.resolve(legacyUserData) === path.resolve(currentUserData)) {
    return
  }

  const markerPath = path.join(currentUserData, MIGRATION_MARKER)
  if (await exists(markerPath)) {
    return
  }

  if (!(await exists(legacyUserData))) {
    return
  }

  if (await exists(path.join(currentUserData, 'config.json'))) {
    logger.info('Skipped legacy profile migration because an AiPot config already exists.', {
      legacyUserData,
      currentUserData,
    })
    await writeFile(
      markerPath,
      JSON.stringify(
        { status: 'skipped', reason: 'current-config-exists', legacyUserData },
        null,
        2,
      ),
      'utf8',
    )
    return
  }

  await mkdir(currentUserData, { recursive: true })
  const entries = await readdir(legacyUserData, { withFileTypes: true })
  const copied: string[] = []
  for (const entry of entries) {
    if (SKIPPED_ENTRIES.has(entry.name) || !MIGRATED_ENTRIES.has(entry.name)) {
      continue
    }

    const source = path.join(legacyUserData, entry.name)
    const destination = path.join(currentUserData, entry.name)
    if (await exists(destination)) {
      continue
    }

    try {
      await copyLegacyEntry(source, destination)
      copied.push(entry.name)
    } catch (error) {
      logger.warn('Failed to copy a legacy profile entry.', {
        entry: entry.name,
        error: error instanceof Error ? error.message : String(error),
      })
    }
  }

  await warnAboutEncryptedSecrets(path.join(currentUserData, 'config.json'))

  await writeFile(
    markerPath,
    JSON.stringify(
      {
        status: 'migrated',
        migratedAt: new Date().toISOString(),
        legacyUserData,
        currentUserData,
        copied,
      },
      null,
      2,
    ),
    'utf8',
  )
  logger.info('Migrated the legacy NeoPot profile.', {
    legacyUserData,
    currentUserData,
    copied,
  })
}
